{# Rendered by ansible/roles/ocp4_workload_kestrel_ingress/tasks/main.yml.
   Solver choice and inputs: ansible/roles/ocp4_workload_kestrel_ingress/defaults/main.yml. #}
apiVersion: cert-manager.io/v1
kind: ClusterIssuer
metadata:
  name: {{ kestrel_ingress_issuer_name }}
spec:
  acme:
    server: {{ kestrel_ingress_acme_server }}
    email: {{ kestrel_ingress_acme_email }}
    solvers:
{% if kestrel_ingress_acme_solver == 'route53-delegated' %}
      - selector:
          dnsZones:
            - {{ kestrel_ingress_dns_zone }}
        dns01:
          route53:
            region: {{ kestrel_ingress_aws_region }}
{% elif kestrel_ingress_acme_solver == 'http01-router' %}
      - http01:
          ingress:
            ingressClassName: {{ kestrel_ingress_router_class }}
{% endif %}

